 53	    /** The component with each binding that names a static method rewritten; any other unit as it is. */
 54	    public static CompilationUnit rewrite(CompilationUnit cu) {
 55	        if (!enabled() || !(cu instanceof Component)) return cu;
 56	        Component c = (Component) cu;
 57	        Aliases aliases = new Aliases();
 58	        List<Decl> decls = new ArrayList<Decl>();
 59	        for (Decl d : c.getDecls()) decls.add(decl(d, null, aliases));
 60	        if (aliases.isEmpty()) return cu;
 61	        List<Import> imports = new ArrayList<Import>(c.getImports());
 62	        Span span = NodeUtil.getSpan(c);
 63	        for (Map.Entry<String, LinkedHashMap<String, String>> e : aliases.entrySet()) {
 64	            List<AliasedSimpleName> names = new ArrayList<AliasedSimpleName>();
 65	            for (Map.Entry<String, String> n : e.getValue().entrySet())
 66	                names.add(NodeFactory.makeAliasedSimpleName(span, NodeFactory.makeId(span, n.getKey()),
 67	                          Option.<IdOrOpOrAnonymousName>some(NodeFactory.makeId(span, n.getValue()))));
 68	            imports.add(NodeFactory.makeImportNames(span, Option.some("java"),
 69	                                                    NodeFactory.makeAPIName(span, e.getKey()), names));
 70	        }
 71	        return new Component(c.getInfo(), c.getName(), imports, decls, c.getComprises(), c.is_native(), c.getExports());
 72	    }
