161	    private static String alias(Aliases aliases, String pkg, String item) {
162	        LinkedHashMap<String, String> inPkg = aliases.get(pkg);
163	        if (inPkg == null) aliases.put(pkg, inPkg = new LinkedHashMap<String, String>());
164	        String alias = inPkg.get(item);
165	        if (alias == null) inPkg.put(item, alias = "builtinPrimitive_" + item.replace('.', '_'));
166	        return alias;
167	    }
